package com.lmspilot.assessment.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="exam_session_events",indexes=@Index(name="idx_exam_session_event",columnList="session_id,occurred_at")) public class ExamSessionEventEntity { @Id public UUID id=UUID.randomUUID(); @Column(name="session_id",nullable=false) public UUID sessionId; @Column(name="user_id",nullable=false) public UUID userId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) public ExamSessionEventType type=ExamSessionEventType.CLIENT_WARNING; @Column(columnDefinition="text") public String details; @Column(name="occurred_at",nullable=false) public Instant occurredAt=Instant.now(); @Column(name="stored_at",nullable=false) public Instant storedAt=Instant.now(); public ExamSessionEventEntity(){} }
